// --- NUMBER COUNTER: plain number rolls up 0 -> Target, lands with a punch
function _numberCounter() {
    var comp = app.project.activeItem;
    if(!comp) return;
    var dur = 4.0;
    var w = comp.width, h = comp.height;
    var ctrl = _uiCtl(comp, "NUMBER COUNTER CONTROLLER", dur, [w/2, h*0.45]);
    _addColorControl(ctrl, "Number Color", [1,1,1]);
    _addSlider(ctrl, "Target", 1000);
    _addSlider(ctrl, "x Multiplier", 1); // AE sliders cap at 1,000,000 — Target * Multiplier goes beyond
    _addSlider(ctrl, "Count Time", 2.2);
    var pre = _uiPrefix(ctrl.name);

    var num = _uiText(comp, "0", Math.round(w*0.13), 6145, 'thisComp.layer("'+ctrl.name+'").effect("Number Color")(1)', dur);
    // count-up drives the text; color is set separately via the style API in the same expression
    num.property("ADBE Text Properties").property("ADBE Text Document").expression =
        "var ctl=thisComp.layer('"+ctrl.name+"'); var spd=ctl.effect('Animation Speed')(1)/100; var tt=(time-inPoint)*spd; "+FMT+
        "function eo3(x){x=Math.max(0,Math.min(1,x));return 1-Math.pow(1-x,3);} var ct=Math.max(0.1,ctl.effect('Count Time')(1)); "+
        "var e=eo3((tt-0.15)/ct); var v=ctl.effect('Target')(1)*Math.max(1,ctl.effect('x Multiplier')(1))*e; var c=ctl.effect('Number Color')(1); "+
        "text.sourceText.style.setFillColor([c[0],c[1],c[2]]).setText(fmt(v));";
    _uiFont(num, "Arial-BoldMT");
    _uiGlowFx(num, w*0.025, 0.55);
    num.parent = ctrl;
    // centring is computed from the count value itself (digit metrics), never from
    // sourceRectAtTime — that expression silently dies on text driven by style.setText
    num.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0, 0]);
    num.property("ADBE Transform Group").property("ADBE Position").expression =
        "var ctl=thisLayer.parent; var spd=ctl.effect('Animation Speed')(1)/100; var tt=(time-inPoint)*spd; " +
        "function eo3(x){x=Math.max(0,Math.min(1,x));return 1-Math.pow(1-x,3);} " +
        "var ct=Math.max(0.1,ctl.effect('Count Time')(1)); " +
        "var mult=1; try{mult=Math.max(1,ctl.effect('x Multiplier')(1));}catch(e){} " +
        "var e=eo3((tt-0.15)/ct); var v=Math.round(ctl.effect('Target')(1)*mult*e); " +
        "var s=''+v; var commas=Math.floor((s.length-1)/3); " +
        "var fsz=text.sourceText.style.fontSize; " +
        "var wpx=s.length*fsz*0.556 + commas*fsz*0.278; " +
        "[-wpx/2, value[1]];";
    // no intro/outro/punch — it just counts and stays until the user trims it
    ctrl.outPoint = comp.duration;
    num.outPoint = comp.duration;

    ctrl.selected = true;
}

// --- TERMINAL UPLOAD: hacker terminal, lines type in, progress bar fills to 100%
function _terminalUpload() {
    var comp = app.project.activeItem;
    if(!comp) return;
    var dur = 7.5;
    var w = comp.width, h = comp.height;
    var ctrl = _uiCtl(comp, "TERMINAL UPLOAD CONTROLLER", dur, [w/2, h*0.42]);
    _addColorControl(ctrl, "Terminal Green", [0.24,0.84,0.55]);
    _addColorControl(ctrl, "Accent Orange", [0.97,0.58,0.10]);
    var cRef = 'thisComp.layer("'+ctrl.name+'")';
    var basePre = "var ctl=thisComp.layer('"+ctrl.name+"'); var spd=ctl.effect('Animation Speed')(1)/100; var t=(time-inPoint)*spd; ";

    var cw = w*0.86, pad = cw*0.07, fs = Math.round(cw*0.046), lh = fs*2.0;
    var ch = pad*2 + lh*7.2;
    var xL = -cw/2 + pad;
    function rowY(i){ return -ch/2 + pad + lh*(0.55 + i); }

    // terminal window
    var card = _uiRRect(comp, "Terminal Window", dur, cw, ch, fs*0.8, '[0.016,0.024,0.018,1]');
    var cardStroke = card.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    cardStroke.property("ADBE Vector Stroke Color").setValue([0.13,0.20,0.15,1]);
    cardStroke.property("ADBE Vector Stroke Width").setValue(Math.max(2, w*0.0025));
    card.parent = ctrl;
    card.property("ADBE Transform Group").property("ADBE Position").setValue([0,0]);
    var cOp = card.property("ADBE Transform Group").property("ADBE Opacity");
    cOp.setValueAtTime(comp.time, 0); cOp.setValueAtTime(comp.time + 0.3, 92);
    var cSc = card.property("ADBE Transform Group").property("ADBE Scale");
    cSc.setValueAtTime(comp.time, [96,96]); cSc.setValueAtTime(comp.time + 0.35, [100,100]);
    try { for (var ck=1; ck<=2; ck++){ cSc.setInterpolationTypeAtKey(ck, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER); cOp.setInterpolationTypeAtKey(ck, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER); } } catch(e){}

    // mac traffic dots
    var dots = comp.layers.addShape();
    dots.name = "Terminal Dots"; dots.inPoint = comp.time; dots.outPoint = comp.time + dur;
    var dotCols = [[1,0.37,0.34,1],[1,0.74,0.18,1],[0.16,0.78,0.25,1]];
    for (var di = 0; di < 3; di++) {
        var dg = dots.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
        var de = dg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Ellipse");
        de.property("ADBE Vector Ellipse Size").setValue([fs*0.5, fs*0.5]);
        var df = dg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
        df.property("ADBE Vector Fill Color").setValue(dotCols[di]);
        dg.property("ADBE Vector Transform Group").property("ADBE Vector Position").setValue([di*fs*0.95, 0]);
    }
    dots.parent = ctrl;
    dots.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0,0]);
    dots.property("ADBE Transform Group").property("ADBE Position").setValue([xL + fs*0.25, rowY(0) - lh*0.15]);
    dots.property("ADBE Transform Group").property("ADBE Opacity").expression = basePre + "(t>0.15)?100:0;";

    // helper: monospace terminal line, appears (or types) at its own delay
    function termLine(str, row, col, mode, delay, cps, cursor) {
        var tl = _uiText(comp, str, fs, 6145, null, dur, col);
        _uiFont(tl, "Consolas");
        tl.parent = ctrl;
        tl.property("ADBE Transform Group").property("ADBE Position").setValue([xL, rowY(row)]);
        if (mode === "type") {
            var esc = str.replace(/'/g, "\\'");
            var cur = (cursor === "stay")
                ? "if(n>=s.length){o+=(Math.floor(t*2.5)%2==0)?'_':'';}else{o+='_';}"
                : "if(n<s.length){o+='_';}";
            tl.property("ADBE Text Properties").property("ADBE Text Document").expression =
                basePre + "var s='"+esc+"'; var n=Math.floor(Math.max(0,(t-"+delay+")*"+cps+")); if(n>s.length)n=s.length; var o=s.substr(0,n); "+cur+" text.sourceText.style.setText(o);";
        } else {
            tl.property("ADBE Transform Group").property("ADBE Opacity").expression = basePre + "(t>"+delay+")?100:0;";
        }
        return tl;
    }
    var GRN = [0.24,0.84,0.55], DIM = [0.25,0.43,0.32], WHT = [0.87,0.91,0.87], ORG = [0.97,0.58,0.10];

    termLine("// 2008-10-31 - anonim server", 1, DIM, "step", 0.4);
    termLine("$ upload bitcoin.pdf", 2, WHT, "type", 0.9, 22);
    termLine("muallif: satoshi_?????", 4, DIM, "step", 3.7);
    termLine("1 hujjat. 9 sahifa.", 5, WHT, "step", 4.4);
    var lastL = termLine("> dunyo endi eskisidek emas", 6, ORG, "type", 5.0, 20, "stay");
    _uiGlowFx(lastL, w*0.018, 0.6);

    // progress bar row: track + left-anchored fill + percent readout
    var bw = cw*0.5, bh = fs*0.55, yBar = rowY(3);
    var track = _uiRRect(comp, "Upload Bar Track", dur, bw, bh, bh/2, '[0.06,0.12,0.08,1]');
    track.parent = ctrl;
    track.property("ADBE Transform Group").property("ADBE Position").setValue([xL + bw/2, yBar]);
    track.property("ADBE Transform Group").property("ADBE Opacity").expression = basePre + "(t>2.0)?100:0;";
    var fill = _uiRRect(comp, "Upload Bar Fill", dur, bw, bh, bh/2, cRef+'.effect("Terminal Green")(1)');
    fill.parent = ctrl;
    fill.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([-bw/2, 0]);
    fill.property("ADBE Transform Group").property("ADBE Position").setValue([xL, yBar]);
    fill.property("ADBE Transform Group").property("ADBE Scale").expression = basePre + "var p=Math.max(0,Math.min(1,(t-2.05)/1.3)); [p*100,100];";
    _uiGlowFx(fill, w*0.012, 0.8);
    var pct = _uiText(comp, "0%", fs, 6145, null, dur, GRN);
    _uiFont(pct, "Consolas");
    pct.parent = ctrl;
    pct.property("ADBE Transform Group").property("ADBE Position").setValue([xL + bw + pad*0.5, yBar]);
    pct.property("ADBE Transform Group").property("ADBE Opacity").expression = basePre + "(t>2.0)?100:0;";
    pct.property("ADBE Text Properties").property("ADBE Text Document").expression =
        basePre + "var p=Math.max(0,Math.min(1,(t-2.05)/1.3)); text.sourceText.style.setText(Math.round(p*100)+'%');";

    ctrl.selected = true;
}

// ============================================================
// APPLE UI KIT — glass blur + SF typography + iOS springs
// Everything is plain editable layers: texts are real text layers,
// colours are fills, motion is keyframes the user can drag.
// ============================================================
function _appleFontTry(tl, names) {
    // AE stores whatever font string you set and substitutes silently at render,
    // so name-validation is impossible — always set the guaranteed last entry (Arial).
    try {
        var d = tl.property("Source Text").value;
        d.font = names[names.length - 1];
        tl.property("Source Text").setValue(d);
    } catch (e) {}
}
// Arial last — guaranteed to exist, so text never falls into AE's default serif
var _SF_BOLD = ["SFProDisplay-Semibold", "SFProText-Semibold", "SegoeUI-Semibold", "SegoeUI-Bold", "Arial-BoldMT"];
var _SF_REG  = ["SFProDisplay-Regular", "SFProText-Regular", "SegoeUI", "ArialMT"];

// real frosted glass: white matte rects -> gaussian-blur adjustment (alpha matte) -> dark tint
function _glassPanel(comp, name, rects, radius, blurAmt) {
    function shapeWith(fillCol, op, nm) {
        var s = comp.layers.addShape(); s.name = nm; s.inPoint = comp.time; s.outPoint = comp.duration;
        for (var i = 0; i < rects.length; i++) {
            var g = s.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
            var r = g.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
            r.property("ADBE Vector Rect Size").setValue([rects[i][2], rects[i][3]]);
            r.property("ADBE Vector Rect Roundness").setValue(radius);
            var f = g.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
            f.property("ADBE Vector Fill Color").setValue(fillCol);
            g.property("ADBE Vector Transform Group").property("ADBE Vector Position").setValue([rects[i][0], rects[i][1]]);
        }
        if (op != null) s.property("ADBE Transform Group").property("ADBE Opacity").setValue(op);
        return s;
    }
    var matte = shapeWith([1, 1, 1, 1], null, name + " Matte");
    var adj = comp.layers.addSolid([0, 0, 0], name + " Glass Blur", comp.width, comp.height, comp.pixelAspect, comp.duration);
    adj.adjustmentLayer = true;
    adj.inPoint = comp.time; adj.outPoint = comp.duration;
    var gb = adj.property("ADBE Effect Parade").addProperty("ADBE Gaussian Blur 2");
    gb.property(1).setValue(blurAmt || 38);
    try { gb.property(3).setValue(1); } catch (e) {}
    try { adj.setTrackMatte(matte, TrackMatteType.ALPHA); }
    catch (e) { try { adj.moveAfter(matte); adj.trackMatteType = TrackMatteType.ALPHA; } catch (e2) {} }
    try { matte.enabled = false; } catch (e) {}
    var tint = shapeWith([0.14, 0.145, 0.18, 1], 62, name + " Tint");
    return { matte: matte, adj: adj, tint: tint };
}
function _appleTxt(comp, str, sizePx, col, bold) {
    var tl = comp.layers.addText(str);
    tl.inPoint = comp.time; tl.outPoint = comp.duration;
    var d = tl.property("Source Text").value;
    d.fontSize = sizePx; d.fillColor = col;
    try { d.justification = ParagraphJustification.LEFT_JUSTIFY; } catch (e) {}
    tl.property("Source Text").setValue(d);
    _appleFontTry(tl, bold ? _SF_BOLD : _SF_REG);
    return tl;
}
function _appleEase(prop) {
    try {
        for (var k = 1; k <= prop.numKeys; k++) {
            var dims = 1; try { dims = prop.value.length || 1; } catch (e0) {}
            var ea = []; for (var d = 0; d < dims; d++) ea.push(new KeyframeEase(0, 66));
            prop.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
            prop.setTemporalEaseAtKey(k, ea, ea);
        }
    } catch (e) {}
}

// --- 1. DYNAMIC ISLAND: black pill expands, music info inside
function _appleDynIsland() {
    var comp = app.project.activeItem; if (!comp) return;
    var w = comp.width, h = comp.height, t0 = comp.time;
    var ctrl = _uiCtl(comp, "DYNAMIC ISLAND CONTROLLER", 5, [w / 2, h * 0.058]);
    ctrl.outPoint = comp.duration;
    var pw0 = w * 0.24, ph0 = w * 0.062, pw1 = w * 0.64, ph1 = w * 0.155;

    var pill = comp.layers.addShape();
    pill.name = "[Apple] Island Pill"; pill.inPoint = t0; pill.outPoint = comp.duration;
    var pg = pill.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var pr = pg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
    // configure the rect fully BEFORE adding the fill — addProperty invalidates sibling refs
    pr.property("ADBE Vector Rect Roundness").setValue(ph1);
    // expand with a soft spring; expression avoids Rect Size keyframe quirks
    pr.property("ADBE Vector Rect Size").expression =
        "var t = time - inPoint - 0.25; " +
        "function eo(x){return 1 - Math.pow(1 - x, 3);} " +
        "var p = eo(Math.max(0, Math.min(1, t / 0.5))); " +
        "var ov = (t > 0 && t < 0.75) ? Math.sin(p * Math.PI) * 0.045 : 0; " +
        "[" + pw0.toFixed(1) + " + " + (pw1 - pw0).toFixed(1) + " * p * (1 + ov * 0.4), " +
        ph0.toFixed(1) + " + " + (ph1 - ph0).toFixed(1) + " * p * (1 + ov)];";
    var pf = pg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    pf.property("ADBE Vector Fill Color").setValue([0.02, 0.02, 0.025, 1]);
    pill.parent = ctrl;
    pill.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]);

    var art = comp.layers.addShape();
    art.name = "[Apple] Island Art"; art.inPoint = t0; art.outPoint = comp.duration;
    var ag = art.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var ar = ag.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
    ar.property("ADBE Vector Rect Size").setValue([w * 0.095, w * 0.095]);
    ar.property("ADBE Vector Rect Roundness").setValue(w * 0.024);
    var af = ag.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    af.property("ADBE Vector Fill Color").setValue([0.92, 0.48, 0.14, 1]);
    art.parent = ctrl;
    art.property("ADBE Transform Group").property("ADBE Position").setValue([-pw1 / 2 + w * 0.075, 0]);

    var lab = _appleTxt(comp, "Now Playing", Math.round(w * 0.023), [0.62, 0.62, 0.66], false);
    lab.parent = ctrl;
    lab.property("ADBE Transform Group").property("ADBE Position").setValue([-pw1 / 2 + w * 0.14, -w * 0.008]);
    var song = _appleTxt(comp, "nytvir - soliqchi", Math.round(w * 0.03), [1, 1, 1], true);
    song.parent = ctrl;
    song.property("ADBE Transform Group").property("ADBE Position").setValue([-pw1 / 2 + w * 0.14, w * 0.03]);

    var eq = comp.layers.addShape();
    eq.name = "[Apple] Island EQ"; eq.inPoint = t0; eq.outPoint = comp.duration;
    for (var b = 0; b < 3; b++) {
        var bg = eq.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
        var br = bg.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
        br.property("ADBE Vector Rect Size").setValue([w * 0.0075, w * 0.042]);
        br.property("ADBE Vector Rect Roundness").setValue(w * 0.004);
        var bf = bg.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
        bf.property("ADBE Vector Fill Color").setValue([0.19, 0.82, 0.35, 1]);
        var bt = bg.property("ADBE Vector Transform Group");
        bt.property("ADBE Vector Position").setValue([b * w * 0.016, w * 0.021]);
        bt.property("ADBE Vector Anchor").setValue([0, w * 0.021]);
        bt.property("ADBE Vector Scale").expression = "[100, 45 + 55*Math.abs(Math.sin(time*5.5 + " + b + "*1.1))];";
    }
    eq.parent = ctrl;
    eq.property("ADBE Transform Group").property("ADBE Position").setValue([pw1 / 2 - w * 0.085, -w * 0.021]);

    var inner = [art, lab, song, eq];
    for (var i = 0; i < inner.length; i++) {
        var op = inner[i].property("ADBE Transform Group").property("ADBE Opacity");
        op.setValueAtTime(t0 + 0.55, 0);
        op.setValueAtTime(t0 + 0.8, 100);
    }
    ctrl.selected = true;
}

