    bolt.property("ADBE Transform Group").property("ADBE Position").setValue([0, w * 0.05]);

    var lbl = _appleTxt(comp, "Quvvatlanmoqda", Math.round(w * 0.028), [0.62, 0.62, 0.66], false);
