    var fx = L.property("ADBE Effect Parade");
    var gw = fx.addProperty("ADBE Gradient Wipe");
    gw.property("ADBE Gradient Wipe-0001").setValueAtTime(t0, 100);
    gw.property("ADBE Gradient Wipe-0001").setValueAtTime(t0 + 1.38, 0);
