    var q3 = prompt("Sarlavha | Tugma | light/dark | rang\nRanglar: blue green orange red pink purple indigo teal brown black\n(sarlavha bo'sh = sarlavhasiz)", PR[3]); if (q3 === null) return;
    var P = _s46Parse(q1, q2, q3);
