    var x = { comp: comp, K: K, W: W, H: H, cx: W / 2, cy: H / 2 - ((H / W > 1.6) ? H * 0.03 : 0), t0: t0, N: N, layers: [], opt: opt };
    x.switchT = []; for (i = 1; i < N; i++) x.switchT.push(t0 + first + (i - 1) * hold);
